window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8e5ea7045261d4ef"]={"versions": [{"id": "FIG-8e5ea7045261d4ef", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Paketformat / Bitfeld-Layout (32-Bit-Raster) im Kontext des AUTOSAR Service Discovery (SOME/IP-SD) Protokolls. Das Diagramm spezifiziert die Struktur der IPv6 Multicast Option zur Übertragung von Netzwerk-Endpunktinformationen innerhalb von SOME/IP-SD-Nachrichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Bitfelder über einem 32-Bit-Offset-Raster (Bits 0 bis 31):</p>\n<ul class=\"fig-list\"><li><code>Length (=0x0015)</code>: 16 Bit (Bit 0 bis 15 der ersten Zeile), statischer Wert 0x0015 (21 Bytes).\n</li><li><code>Type (=0x16)</code>: 8 Bit (Bit 16 bis 23 der ersten Zeile), Options-Typ-Kennung für IPv6 Multicast Option.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 24 bis 31 der ersten Zeile), reserviertes Feld.\n</li><li><code>IPv6-Address [128bit]</code>: 128 Bit (4 Zeilen à 32 Bit), IPv6-Multicast-Zieladresse.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 0 bis 7 der letzten Zeile), reserviertes Feld.\n</li><li><code>L4-Proto (UDP/...)</code>: 8 Bit (Bit 8 bis 15 der letzten Zeile), Transportprotokoll-Identifikator (z. B. UDP).\n</li><li><code>Port Number</code>: 16 Bit (Bit 16 bis 31 der letzten Zeile), Layer-4-Portnummer.\n</li><li>Maßpfeil: <code>Covered by Length (incl. Reserved)</code>, kennzeichnet die Längenabdeckung ab dem ersten Reserved-Feld (Byte 3 der Option) bis zum Ende der Option (insgesamt 21 Bytes = 1 Byte Reserved + 16 Bytes IPv6 + 1 Byte Reserved + 1 Byte L4-Proto + 2 Bytes Port).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Binärstruktur zur Serialisierung und Deserialisierung. Die Option wird als Teil des Options-Arrays einer SOME/IP-SD-Nachricht kodiert und von Entries (z. B. Eventgroup-Subskriptionen) referenziert, um Multicast-Gruppenadressen und UDP-Ports für Event-Benachrichtigungen bereitzustellen. Der Empfänger extrahiert anhand des Type-Felds 0x16 und der Länge 0x0015 die IPv6-Multicast-Adresse sowie Transportparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Datenformat für AUTOSAR SOME/IP Service Discovery. Die Feldlängen, Bit-Ausrichtungen (Big-Endian-Netzwerk-Byte-Order) und festen Werte (<code>Length = 0x0015</code>, <code>Type = 0x16</code>, <code>Reserved = 0x00</code>) sind zwingend einzuhalten. Reservierte Felder müssen mit 0x00 belegt und bei der Deserialisierung ignoriert werden. Die Längenangabe schließt das nachfolgende Reserved-Byte sowie alle Nutzdatenfelder ein.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-59e2c70f7300aadc", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Paketformat / Bitfeld-Layout (32-Bit-Raster) im Kontext des AUTOSAR Service Discovery (SOME/IP-SD) Protokolls. Das Diagramm spezifiziert die Struktur der IPv6 Multicast Option zur Übertragung von Netzwerk-Endpunktinformationen innerhalb von SOME/IP-SD-Nachrichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Bitfelder über einem 32-Bit-Offset-Raster (Bits 0 bis 31):</p>\n<ul class=\"fig-list\"><li><code>Length (=0x0015)</code>: 16 Bit (Bit 0 bis 15 der ersten Zeile), statischer Wert 0x0015 (21 Bytes).\n</li><li><code>Type (=0x16)</code>: 8 Bit (Bit 16 bis 23 der ersten Zeile), Options-Typ-Kennung für IPv6 Multicast Option.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 24 bis 31 der ersten Zeile), reserviertes Feld.\n</li><li><code>IPv6-Address [128bit]</code>: 128 Bit (4 Zeilen à 32 Bit), IPv6-Multicast-Zieladresse.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 0 bis 7 der letzten Zeile), reserviertes Feld.\n</li><li><code>L4-Proto (UDP/...)</code>: 8 Bit (Bit 8 bis 15 der letzten Zeile), Transportprotokoll-Identifikator (z. B. UDP).\n</li><li><code>Port Number</code>: 16 Bit (Bit 16 bis 31 der letzten Zeile), Layer-4-Portnummer.\n</li><li>Maßpfeil: <code>Covered by Length (incl. Reserved)</code>, kennzeichnet die Längenabdeckung ab dem ersten Reserved-Feld (Byte 3 der Option) bis zum Ende der Option (insgesamt 21 Bytes = 1 Byte Reserved + 16 Bytes IPv6 + 1 Byte Reserved + 1 Byte L4-Proto + 2 Bytes Port).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Binärstruktur zur Serialisierung und Deserialisierung. Die Option wird als Teil des Options-Arrays einer SOME/IP-SD-Nachricht kodiert und von Entries (z. B. Eventgroup-Subskriptionen) referenziert, um Multicast-Gruppenadressen und UDP-Ports für Event-Benachrichtigungen bereitzustellen. Der Empfänger extrahiert anhand des Type-Felds 0x16 und der Länge 0x0015 die IPv6-Multicast-Adresse sowie Transportparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Datenformat für AUTOSAR SOME/IP Service Discovery. Die Feldlängen, Bit-Ausrichtungen (Big-Endian-Netzwerk-Byte-Order) und festen Werte (<code>Length = 0x0015</code>, <code>Type = 0x16</code>, <code>Reserved = 0x00</code>) sind zwingend einzuhalten. Reservierte Felder müssen mit 0x00 belegt und bei der Deserialisierung ignoriert werden. Die Längenangabe schließt das nachfolgende Reserved-Byte sowie alle Nutzdatenfelder ein.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9f0b62da42672bce", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Paketformat / Bitfeld-Layout (32-Bit-Raster) im Kontext des AUTOSAR Service Discovery (SOME/IP-SD) Protokolls. Das Diagramm spezifiziert die Struktur der IPv6 Multicast Option zur Übertragung von Netzwerk-Endpunktinformationen innerhalb von SOME/IP-SD-Nachrichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Bitfelder über einem 32-Bit-Offset-Raster (Bits 0 bis 31):</p>\n<ul class=\"fig-list\"><li><code>Length (=0x0015)</code>: 16 Bit (Bit 0 bis 15 der ersten Zeile), statischer Wert 0x0015 (21 Bytes).\n</li><li><code>Type (=0x16)</code>: 8 Bit (Bit 16 bis 23 der ersten Zeile), Options-Typ-Kennung für IPv6 Multicast Option.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 24 bis 31 der ersten Zeile), reserviertes Feld.\n</li><li><code>IPv6-Address [128bit]</code>: 128 Bit (4 Zeilen à 32 Bit), IPv6-Multicast-Zieladresse.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 0 bis 7 der letzten Zeile), reserviertes Feld.\n</li><li><code>L4-Proto (UDP/...)</code>: 8 Bit (Bit 8 bis 15 der letzten Zeile), Transportprotokoll-Identifikator (z. B. UDP).\n</li><li><code>Port Number</code>: 16 Bit (Bit 16 bis 31 der letzten Zeile), Layer-4-Portnummer.\n</li><li>Maßpfeil: <code>Covered by Length (incl. Reserved)</code>, kennzeichnet die Längenabdeckung ab dem ersten Reserved-Feld (Byte 3 der Option) bis zum Ende der Option (insgesamt 21 Bytes = 1 Byte Reserved + 16 Bytes IPv6 + 1 Byte Reserved + 1 Byte L4-Proto + 2 Bytes Port).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Binärstruktur zur Serialisierung und Deserialisierung. Die Option wird als Teil des Options-Arrays einer SOME/IP-SD-Nachricht kodiert und von Entries (z. B. Eventgroup-Subskriptionen) referenziert, um Multicast-Gruppenadressen und UDP-Ports für Event-Benachrichtigungen bereitzustellen. Der Empfänger extrahiert anhand des Type-Felds 0x16 und der Länge 0x0015 die IPv6-Multicast-Adresse sowie Transportparameter.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Datenformat für AUTOSAR SOME/IP Service Discovery. Die Feldlängen, Bit-Ausrichtungen (Big-Endian-Netzwerk-Byte-Order) und festen Werte (<code>Length = 0x0015</code>, <code>Type = 0x16</code>, <code>Reserved = 0x00</code>) sind zwingend einzuhalten. Reservierte Felder müssen mit 0x00 belegt und bei der Deserialisierung ignoriert werden. Die Längenangabe schließt das nachfolgende Reserved-Byte sowie alle Nutzdatenfelder ein.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8e5ea7045261d4ef", "to": "FIG-59e2c70f7300aadc", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-59e2c70f7300aadc", "to": "FIG-9f0b62da42672bce", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
